package fr.gemsofrod.encyclopedie.data

/** Traductions It des fiches météorites (nom, descriptions, intérêt en joaillerie). */
object MeteoriteTranslationsIt {
    val data: Map<String, MeteoriteTranslation> = mapOf(
        "meteorite-gibeon" to MeteoriteTranslation(
            nom = "Gibeon",
            descriptionCourte = "Una pioggia di frammenti caduta in Namibia millenni fa, diventata il riferimento mondiale del gioiello meteoritico.",
            descriptionLongue = "Scoperta dai Nama della Namibia ben prima del suo riconoscimento scientifico nel 1836, Gibeon deve la propria notorietà alle sue splendide figure di Widmanstätten: un reticolo geometrico di kamacite e taenite, invisibile a occhio nudo, rivelato da un semplice attacco con acido nitrico su una superficie levigata. Il suo vasto campo di dispersione ne ha fatto la meteorite ferrosa più disponibile e più lavorata al mondo, tanto in pendenti quanto in lame di coltelli d'arte.",
            interetJoaillerie = "Elevato: pendenti, gemelli da polso, lame di coltello. La meteorite ferrosa più utilizzata in gioielleria."
        ),
        "meteorite-sikhote-alin" to MeteoriteTranslation(
            nom = "Sikhote-Alin",
            descriptionCourte = "La pioggia di ferro più spettacolare del XX secolo, filmata in pieno giorno sopra la taiga russa.",
            descriptionLongue = "Il 12 febbraio 1947, una massa ferrosa di circa venti tonnellate esplode in volo sopra i monti Sikhote-Alin, nell'Estremo Oriente russo, disperdendo migliaia di frammenti su diversi chilometri quadrati. A differenza della maggior parte delle cadute storiche, questa fu osservata e documentata quasi in diretta. Gli esemplari, costellati dei caratteristici regmaglipti tipici di una combustione atmosferica violenta, sono oggi tra le meteoriti da collezione più abbondanti e riconoscibili al mondo.",
            interetJoaillerie = "Da medio a elevato: la caduta meglio documentata del XX secolo, forte richiesta da parte dei collezionisti per gli esemplari dalle forme scultoree"
        ),
        "meteorite-campo-del-cielo" to MeteoriteTranslation(
            nom = "Campo del Cielo",
            descriptionCourte = "Un campo di crateri conosciuto dalle popolazioni autoctone ben prima degli europei, oggi la fonte più abbondante di ferro meteoritico sul mercato.",
            descriptionLongue = "Caduto diversi millenni fa nel Chaco argentino, questo campo di meteoriti deve il proprio nome — «Campo del Cielo» — alle popolazioni locali che lo conoscevano ben prima del suo studio scientifico nel XVIII secolo. Con oltre cento tonnellate di materiale ritrovato, tra cui il celebre blocco Gancedo di oltre 30 tonnellate, Campo del Cielo è diventato la fonte più accessibile e più lavorata per la scultura, l'incisione e la gioielleria in ferro meteoritico.",
            interetJoaillerie = "Ottimo rapporto qualità-prezzo: la meteorite ferrosa più accessibile sul mercato grazie a una massa totale considerevole"
        ),
        "meteorite-muonionalusta" to MeteoriteTranslation(
            nom = "Muonionalusta",
            descriptionCourte = "Trovata nell'estremo nord della Svezia, rinomata per il motivo di Widmanstätten più fine e regolare in assoluto.",
            descriptionLongue = "Scoperta nel 1906 in Lapponia svedese, Muonionalusta è oggi una delle meteoriti ferrose più apprezzate da coltellinai e orafi d'arte: la sua struttura ottaedrica fine dà origine, dopo l'attacco acido, a un reticolo di Widmanstätten di una regolarità e finezza raramente eguagliate. Si stima che la sua caduta risalga a oltre un milione di anni fa, il che ne fa anche una delle cadute conosciute più antiche ancora recuperate in quantità significative.",
            interetJoaillerie = "Elevato: considerata tra le meteoriti con il più bel motivo di Widmanstätten conosciuto"
        ),
        "meteorite-nantan" to MeteoriteTranslation(
            nom = "Nantan",
            descriptionCourte = "Conosciuta localmente ben prima della sua scoperta scientifica, una delle meteoriti ferrose più economiche sul mercato.",
            descriptionLongue = "Frammenti di Nantan venivano sfruttati come minerale di ferro dagli abitanti locali fin dal XVI secolo, ben prima che la pioggia di meteoriti fosse ufficialmente riconosciuta nel 1958. La sua ingente massa totale e il prezzo molto accessibile ne hanno fatto un classico punto d'ingresso per chi si avvicina alla lapidazione meteoritica, nonostante un motivo di Widmanstätten meno fine rispetto a quello di Muonionalusta o Gibeon.",
            interetJoaillerie = "Economica e abbondante, molto utilizzata in bigiotteria e per l'avvicinamento alla lapidazione meteoritica"
        ),
        "meteorite-canyon-diablo" to MeteoriteTranslation(
