            descriptionCourte = "Scoperta nel 1881 nelle pianure del Kansas, una delle pallasiti storiche del Nord America.",
            descriptionLongue = "Trovata nel 1881 nella contea di Lyon, in Kansas, Admire è tra le prime pallasiti nordamericane descritte scientificamente, insieme alla vicina Brenham, scoperta nello stesso Stato pochi anni dopo. Le sue fette, con olivine ben distribuite in una matrice metallica densa, restano un classico apprezzato da collezionisti e orafi che lavorano le pallasiti americane.",
            interetJoaillerie = "Elevato, storico: una delle prime pallasiti americane censite"
        ),
        "meteorite-fukang" to MeteoriteTranslation(
