            descriptionCourte = "Scoperta nel 2000, una massa di circa mille chilogrammi con olivine translucide di una qualità raramente eguagliata.",
            descriptionLongue = "Scoperta nel 2000 sui monti Tianshan, in Cina, Fukang ha restituito una massa totale di circa mille chilogrammi con cristalli di olivina eccezionalmente grandi e translucidi, esposti in diversi importanti musei del mondo. Le rare fette giunte sul mercato privato si negoziano tra i prezzi più alti di tutta la lapidazione meteoritica, allo stesso livello delle più belle pietre fini.",
            interetJoaillerie = "Prestigio assoluto: una delle più grandi e più belle pallasiti mai scoperte"
        ),
        "meteorite-chelyabinsk" to MeteoriteTranslation(
            nom = "Chelyabinsk",
            descriptionCourte = "Il bolide filmato da migliaia di videocamere di bordo russe nel 2013, diventato la caduta meglio documentata dell'era digitale.",
            descriptionLongue = "Il 15 febbraio 2013, un asteroide di una ventina di metri esplode nell'atmosfera sopra gli Urali, generando un'onda d'urto che ferisce oltre un migliaio di persone a causa dei vetri infranti, senza causare vittime dirette. L'evento, ripreso da innumerevoli videocamere di bordo, ne ha fatto la caduta di meteorite meglio filmata della storia, e i frammenti ritrovati nella neve circostante restano attivamente ricercati dai collezionisti di tutto il mondo.",
            interetJoaillerie = "Medio: evento ampiamente mediatizzato (bolide filmato da migliaia di dashcam), forte richiesta da parte dei collezionisti"
        ),
        "meteorite-peekskill" to MeteoriteTranslation(
            nom = "Peekskill",
            descriptionCourte = "La meteorite che colpì una Chevrolet Malibu parcheggiata a New York, filmata in pieno volo dagli spettatori di una partita di football americano.",
            descriptionLongue = "Il 9 ottobre 1992, un bolide che attraversa il cielo di diversi Stati americani — filmato da numerosi testimoni durante partite di football scolastico — termina la sua corsa con l'impatto di un frammento di 12 kg sulla parte posteriore di una Chevrolet Malibu parcheggiata a Peekskill, New York. L'aneddoto ha reso questa condrite famosa in tutto il mondo; i frammenti, rari, vengono conservati soprattutto allo stato grezzo per preservare la loro crosta di fusione, garanzia di autenticità e di valore da collezione.",
            interetJoaillerie = "Medio: aneddoto molto noto (il bolide colpì un'automobile parcheggiata), forte valore narrativo da collezione"
        ),
        "meteorite-nwa-chondrite" to MeteoriteTranslation(
            nom = "Condrite del Sahara (NWA generica)",
            descriptionCourte = "Gli innumerevoli ritrovamenti sahariani, catalogati sotto la denominazione generica \"Northwest Africa\", che alimentano la maggior parte del mercato della condrite.",
            descriptionLongue = "Dagli anni '90, l'aridità e la leggibilità del deserto del Sahara ne fanno il terreno di scoperta di meteoriti più prolifico al mondo, catalogate collettivamente sotto la denominazione \"Northwest Africa\" seguita da un numero (NWA 1, NWA 869...). Queste condriti ordinarie, di classificazione variabile e spesso meno documentate rispetto a una caduta osservata, offrono comunque la porta d'ingresso più accessibile alla collezione e al taglio di meteoriti pietrose.",
            interetJoaillerie = "Economica, ampiamente disponibile: l'ingresso più diffuso per scoprire la condrite tagliata"
        ),
        "meteorite-murchison" to MeteoriteTranslation(
            nom = "Murchison",
            descriptionCourte = "Una delle meteoriti più studiate al mondo: contiene amminoacidi extraterrestri anteriori al sistema solare.",
            descriptionLongue = "Caduta in Australia nel 1969, Murchison è diventata una delle meteoriti più analizzate della storia scientifica: ha restituito oltre 70 amminoacidi di origine extraterrestre, oltre a granuli di polvere presolare più antichi del Sole stesso. La sua estrema fragilità e il suo valore scientifico ne escludono qualsiasi uso lapidario o gioielliero: figura qui a scopo di cultura generale, non come materiale da taglio.",
            interetJoaillerie = "Nullo in gioielleria; fondamentale nella ricerca sulle origini della vita"
        ),
        "meteorite-allende" to MeteoriteTranslation(
            nom = "Allende",
            descriptionCourte = "Una pioggia di frammenti caduta sul Messico, contenente alcune delle materie più antiche del sistema solare.",
            descriptionLongue = "Caduta nel febbraio 1969 sopra Chihuahua, Allende ha disperso diverse tonnellate di frammenti su un vasto territorio, rendendo questa caduta una delle più ampiamente studiate al mondo. Le sue inclusioni biancastre, ricche di calcio e alluminio, sono tra i più antichi solidi conosciuti del sistema solare, precedenti di diversi milioni di anni la formazione della Terra. Come Murchison, la sua fragilità ne riserva l'uso alla ricerca e al collezionismo, mai al taglio.",
            interetJoaillerie = "Nullo in gioielleria; contiene alcuni dei solidi più antichi conosciuti del sistema solare"
        ),
        "meteorite-hoba" to MeteoriteTranslation(
            nom = "Hoba",
            descriptionCourte = "La più grande meteorite conosciuta sulla Terra, rimasta esattamente dove è caduta circa 80.000 anni fa.",
            descriptionLongue = "Scoperta nel 1920 in una fattoria namibiana, Hoba è, con le sue circa sessanta tonnellate, la meteorite più massiccia mai ritrovata intatta sulla Terra: le sue dimensioni e la forma piatta le hanno permesso di non affondare né frammentarsi all'impatto. Dichiarata monumento nazionale namibiano, non è mai stata spostata né tagliata e si può ancora visitare nel suo sito di caduta originario; figura qui come riferimento culturale, non come materiale disponibile.",
            interetJoaillerie = "Nullo (non commercializzata); interesse puramente museale e turistico"
        ),
        "meteorite-willamette" to MeteoriteTranslation(
            nom = "Willamette",
            descriptionCourte = "La più grande meteorite trovata negli Stati Uniti, considerata sacra dal popolo Clackamas con il nome di Tomanowos.",
            descriptionLongue = "Scoperta nel XIX secolo in Oregon, questa massa di oltre 15 tonnellate è venerata da generazioni dal popolo Clackamas con il nome di Tomanowos, un visitatore celeste portatore di guarigione. Esposta oggi all'American Museum of Natural History nell'ambito di un accordo con la tribù, non è mai stata oggetto di taglio commerciale e non lo sarà mai: figura qui per la sua importanza storica e culturale, non come materiale lapidario.",
            interetJoaillerie = "Nullo commercialmente; patrimonio culturale di primaria importanza per il popolo Clackamas"
        ),
        "meteorite-ensisheim" to MeteoriteTranslation(
            nom = "Ensisheim",
            descriptionCourte = "La più antica caduta di meteorite documentata d'Europa, avvenuta in Alsazia nel 1492 e subito considerata un presagio.",
            descriptionLongue = "Il 7 novembre 1492, un blocco di circa 127 kg si schianta in un campo di grano vicino a Ensisheim, in Alsazia, sotto gli occhi di numerosi testimoni. L'evento, avvenuto pochi mesi dopo il ritorno di Cristoforo Colombo, fu interpretato come un presagio dalle autorità dell'epoca, fino al re Massimiliano I, che venne di persona a esaminare la pietra. Conservata da allora in gran parte nelle collezioni locali, è la più antica caduta di meteorite d'Europa di cui si conoscano con esattezza data e luogo.",
            interetJoaillerie = "Nullo commercialmente; patrimonio storico (la più antica caduta documentata d'Europa)"
        ),
        "meteorite-nwa-7034" to MeteoriteTranslation(
            nom = "NWA 7034 «Black Beauty»",
            descriptionCourte = "Un frammento di crosta marziana tra i più antichi conosciuti, soprannominato «Black Beauty» per il suo colore carbone.",
            descriptionLongue = "Scoperta nel Sahara nel 2011, NWA 7034 è una delle poche meteoriti marziane conosciute e una delle più antiche: risalirebbe a oltre 4,4 miliardi di anni fa, ovvero quasi all'età di Marte stesso. La sua estrema rarità — poche centinaia di grammi censiti nel mondo — ne fa uno dei materiali più costosi del pianeta, ben al di là del diamante a parità di peso; solo minuscoli micro-frammenti certificati circolano occasionalmente, incastonati in resina in creazioni di altissima eccezione.",
            interetJoaillerie = "Molto elevato come curiosità ultra-rara; praticamente mai accessibile nella pratica"
        ),
        "meteorite-alh-84001" to MeteoriteTranslation(
            nom = "ALH 84001",
            descriptionCourte = "La meteorite marziana che nel 1996 riaccese il dibattito mondiale su una possibile vita fossile extraterrestre.",
            descriptionLongue = "Trovata in Antartide nel 1984, questa roccia vecchia di 4 miliardi di anni divenne celebre nel 1996 quando ricercatori della NASA vi identificarono strutture che ricordavano fossili batterici microscopici — un annuncio che fece il giro dei giornali di tutto il mondo e che resta dibattuto ancora oggi. Conservata come reperto scientifico di primo piano, non è mai stata e non sarà mai disponibile per il taglio o la vendita.",
            interetJoaillerie = "Nullo commercialmente; di grande rilievo scientifico"
        ),
        "meteorite-lunaire-nwa" to MeteoriteTranslation(
            nom = "Meteorite lunare (tipo NWA)",
            descriptionCourte = "Rari frammenti della superficie lunare, espulsi da impatti e poi caduti sulla Terra dopo un lungo viaggio nello spazio.",
            descriptionLongue = "Proiettati nello spazio da impatti di asteroidi sulla superficie della Luna, questi frammenti hanno vagato per centinaia di migliaia, se non milioni di anni prima di ricadere sulla Terra, ritrovati principalmente nel deserto del Sahara o in Antartide. Estremamente rari — meno di duecento chilogrammi censiti in totale, considerando tutti i ritrovamenti lunari — esistono sul mercato della gioielleria solo sotto forma di minuscole polveri certificate, incastonate a titolo di assoluta curiosità piuttosto che come materiale gemmologico.",
            interetJoaillerie = "Elevato come curiosità («gioiello di Luna») nonostante una disponibilità pressoché nulla"
        ),
    )
}
